              "order": 3,
              "title": "You can get the access card at the security gate",
              "instructions": "• You can get the access card at the security gate. The resort HOA requires one (1) access card per guest vehicle at a cost of $20 per card, with a maximum of six (6) vehicles allowed per property.",
