              "instructions": "• The  instructions are different from our other homes, so I want to make sure you know what to let the guests know when they contact you.  - Update on 17/05/2025 -Kiruthika. AC upstairs: When you arrive, the upstairs AC will be set to \"Run\" mode. To adjust the temperature, use the side buttons on the thermostat. The lowest setting allowed is 72°F. After selecting your desired temperature (72°F or higher), press the Hold button to maintain that setting. The system will then adjust to your selected temperature. Downstairs:",
