              "instructions": "• Please note the team reported an issue, but will need your help while the developers find a solution, see below:You can work around this current error by changing the start date to a different date than the original start date assigned when the Add Visitor Form pops up. You can then change the Start date to any date, including the original date, and the end date can then be edited to any date within the 45 day Pass Parameters. The proportia Website for Solterra changed over night , please see email from the HOA, you will need to use the new links, there is also videos on how to use th website, please let me know if you have any questions. Good Morning, Solterra Resort Homeowners and Property Managers,",
