          "steps": [
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-1",
              "order": 1,
              "title": "Storey Lake Resort is a vacation rental community in Kissimmee, Florid",
              "instructions": "• Storey Lake Resort is a vacation rental community in Kissimmee, Florida that offers a variety of amenities for guests to enjoy. Two clubhouses feature a lazy river, fitness centers, and tiki bars that serve food and drinks. There are also waterslides, a splash pad, mini-golf, playgrounds, and resort-style pools. A free golf cart shuttle service transports guests to the different clubhouses and their vacation rentals.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-2",
              "order": 2,
              "title": "Here is a more detailed list of the resort amenities:",
              "instructions": "• Here is a more detailed list of the resort amenities:",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-3",
              "order": 3,
              "title": "Two clubhouses: Each clubhouse has a lazy river, a fitness center, and",
              "instructions": "• Two clubhouses: Each clubhouse has a lazy river, a fitness center, and a tiki bar. The tiki bars serve food and drinks, so you can relax and enjoy a cold beverage while you watch the kids play in the lazy river.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-4",
              "order": 4,
              "title": "Waterslides: There are two waterslides at Storey Lake Resort, one for",
              "instructions": "• Waterslides: There are two waterslides at Storey Lake Resort, one for adults and one for kids. The adult waterslide is a dual slide that is sure to get your heart racing. The kid’s waterslide is a gentle slide that is perfect for younger children.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-5",
              "order": 5,
              "title": "Splash pad: The splash pad is a great place for kids to cool off on a",
              "instructions": "• Splash pad: The splash pad is a great place for kids to cool off on a hot day. There are a variety of water features to play in, including fountains, spray jets, and a dumping bucket.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-6",
              "order": 6,
              "title": "Mini-golf: The mini-golf course is a fun activity for the whole family",
              "instructions": "• Mini-golf: The mini-golf course is a fun activity for the whole family. There are 18 holes of challenging but fun mini-golf.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-7",
              "order": 7,
              "title": "Playgrounds: There are two playgrounds at Storey Lake Resort, one for",
              "instructions": "• Playgrounds: There are two playgrounds at Storey Lake Resort, one for younger children and one for older children. The playgrounds have a variety of equipment to climb on and play with.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-8",
              "order": 8,
              "title": "Resort-style pools: There are three resort-style pools at Storey Lake",
              "instructions": "• Resort-style pools: There are three resort-style pools at Storey Lake Resort, one for adults, one for families, and one for the kids. The pools are all heated, so you can enjoy them year-round.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-9",
              "order": 9,
              "title": "Golf cart shuttle service: A free golf cart shuttle service transports",
              "instructions": "• Golf cart shuttle service: A free golf cart shuttle service transports guests to the different clubhouses and their vacation rentals. This is a great way to get around the resort without having to walk or drive.",
              "type": "normal",
              "branches": []
            },
            {
              "id": "villakey-storey-lake-4804-procedure-001-step-10",
              "order": 10,
              "title": "Storey Lake Resort is the perfect place to relax and have fun with you",
              "instructions": "• Storey Lake Resort is the perfect place to relax and have fun with your family. With its variety of amenities, there is something for everyone to enjoy.",
              "type": "normal",
              "branches": []
            }
          ],
          "completionInstruction": "Complete the procedure after all applicable instructions have been followed and any required update/escalation has been made."
