              "order": 3,
              "title": "Within 24 hours of your arrival, you must register with the front desk",
              "instructions": "• Within 24 hours of your arrival, you must register with the front desk in the Clubhouse. On check-in you will receive information on registering your vehicle(s), and a Gate Pass for the resort fast entry lane will be issued for each vehicle, for which a fee of $20 per card will be payable. The card(s) will be good for the duration of your stay.",
              "type": "normal",
