              "order": 5,
              "title": "Once you arrive at the home you may park your car in the driveway",
              "instructions": "• Once you arrive at the home you may park your car in the driveway. On the front door you will see a keypad. You will enter the code we provide you on the day before check-in. This will provide you access to the home for the length of your stay.",
              "type": "normal",
