              "order": 1,
              "title": "PARKINGDon’t get towed",
              "instructions": "• PARKINGDon’t get towed! Parking limits are strictly enforced. Two cars per driveway or in designated parking areas. Check at the clubhouse for more information. Never park on the grass or block traffic! Guests must follow posted street signs required by the county. Vacant lots next to homes are not to be used for any type of purpose, including parking.",
