              "instructions": "• Please make sure to locate the main entrance of the resort where the guard is located. If you have returned your Rental Agreement, your name should be pre registered with the gate. Just in case, have a printed or digital copy of your agreement and/or booking confirmation handy. IMPORTANT - There is a THREE CAR LIMIT in Windsor Hills. See additional parking instructions in the separate card.",
